{
  "apikey_info": {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "title": "DNSResolution",
    "description": "Schema describing the DNS resolution result for a domain.",
    "type": "object",
    "properties": {
      "domain": {
        "type": "string",
        "description": "The domain name that was queried."
      },
      "records": {
        "type": "array",
        "description": "List of DNS records returned for the domain.",
        "items": {
          "type": "object",
          "properties": {
            "type": {
              "type": "string",
              "enum": ["A", "AAAA", "CNAME", "MX", "TXT", "NS", "SOA"],
              "description": "The DNS record type."
            },
            "value": {
              "type": "string",
              "description": "The value of the DNS record."
            },
            "ttl": {
              "type": "integer",
              "description": "Time-to-live for the record in seconds."
            }
          },
          "required": ["type", "value"]
        }
      }
    },
    "required": ["domain", "records"]
  }
}
```

